const getRingBuffer=moduleId=>{const audioWorkletGlobalScope=globalThis;class RingBuffer{static getStorageForCapacity(capacity,Type){if(!Type.BYTES_PER_ELEMENT){throw new Error("Pass in a ArrayBuffer subclass")}const bytes=8+(capacity+1)*Type.BYTES_PER_ELEMENT;return new SharedArrayBuffer(bytes)}constructor(sab,Type){if(!Type.BYTES_PER_ELEMENT){throw new Error("Pass a concrete typed array class as second argument")}this._Type=Type;this._capacity=(sab.byteLength-8)/Type.BYTES_PER_ELEMENT;this.buf=sab;this.write_ptr=new Uint32Array(this.buf,0,1);this.read_ptr=new Uint32Array(this.buf,4,1);this.storage=new Type(this.buf,8,this._capacity)}get type(){return this._Type.name}push(elements){const rd=Atomics.load(this.read_ptr,0);const wr=Atomics.load(this.write_ptr,0);if((wr+1)%this._storageCapacity()===rd){return 0}const toWrite=Math.min(this._availableWrite(rd,wr),elements.length);const firstPart=Math.min(this._storageCapacity()-wr,toWrite);const secondPart=toWrite-firstPart;this._copy(elements,0,this.storage,wr,firstPart);this._copy(elements,firstPart,this.storage,0,secondPart);Atomics.store(this.write_ptr,0,(wr+toWrite)%this._storageCapacity());return toWrite}pop(elements){const rd=Atomics.load(this.read_ptr,0);const wr=Atomics.load(this.write_ptr,0);if(wr===rd){return 0}const isArray=!Number.isInteger(elements);const toRead=Math.min(this._availableRead(rd,wr),isArray?elements.length:elements);if(isArray){const firstPart=Math.min(this._storageCapacity()-rd,toRead);const secondPart=toRead-firstPart;this._copy(this.storage,rd,elements,0,firstPart);this._copy(this.storage,0,elements,firstPart,secondPart)}Atomics.store(this.read_ptr,0,(rd+toRead)%this._storageCapacity());return toRead}get empty(){const rd=Atomics.load(this.read_ptr,0);const wr=Atomics.load(this.write_ptr,0);return wr===rd}get full(){const rd=Atomics.load(this.read_ptr,0);const wr=Atomics.load(this.write_ptr,0);return(wr+1)%this._capacity!==rd}get capacity(){return this._capacity-1}get availableRead(){const rd=Atomics.load(this.read_ptr,0);const wr=Atomics.load(this.write_ptr,0);return this._availableRead(rd,wr)}get availableWrite(){const rd=Atomics.load(this.read_ptr,0);const wr=Atomics.load(this.write_ptr,0);return this._availableWrite(rd,wr)}_availableRead(rd,wr){if(wr>rd){return wr-rd}return wr+this._storageCapacity()-rd}_availableWrite(rd,wr){let rv=rd-wr-1;if(wr>=rd){rv+=this._storageCapacity()}return rv}_storageCapacity(){return this._capacity}_copy(input,offsetInput,output,offsetOutput,size){for(let i=0;i<size;i++){output[offsetOutput+i]=input[offsetInput+i]}}}if(audioWorkletGlobalScope.AudioWorkletProcessor){const ModuleScope=audioWorkletGlobalScope.webAudioModules.getModuleScope(moduleId);if(!ModuleScope.RingBuffer)ModuleScope.RingBuffer=RingBuffer}return RingBuffer};export default getRingBuffer;